/**
 * Transform represents a column transform that registers in the alias registry.
 * Transforms don't create subqueries - they register handlers that resolve aliases to SQL expressions.
 *
 * Requirements by transform type:
 * json_unpack: Args is optional (not used)
 */
export type Transform = {
    /**
     * Alias is the name used to reference the transform result in subsequent pipes.
     */
    alias: string;
    /**
     * Args contains transform-specific arguments.
     */
    args?: Array<string>;
    /**
     * SourceColumn is the column to transform.
     */
    sourceColumn: string;
    /**
     * Type specifies the kind of transform to apply.
     * json_unpack TransformTypeJsonUnpack  TransformTypeJsonUnpack unpacks JSON fields with prefix matching
     * datetime_extract TransformTypeDatetimeExtract  TransformTypeDatetimeExtract extracts date/time parts from timestamps
     */
    type: 'json_unpack' | 'datetime_extract';
};

