/**
 * UnfurlCard is the provider-agnostic card POST /api/unfurl resolves a shared
 * link to. ExternalRefID is the resolved asset's stable identity — not
 * necessarily anything present verbatim in the URL. Fields is display-ordered:
 * the slice order IS the order a renderer shows them in.
 */
export type UnfurlCard = {
    displayType?: string;
    externalRefId?: string;
    fields?: Array<UnfurlCardField>;
    title?: string;
    type?: string;
};

/**
 * UnfurlCardField is one labeled value on an unfurl card. Value is typed per
 * ValueType ("string" or "integer") so a provider-side renderer (Slack Work
 * Object today) can pick the right field type without inspecting the Go
 * value's kind. Link is omitted when the field carries no follow-up URL.
 */
export type UnfurlCardField = {
    key?: string;
    label?: string;
    link?: string;
    value?: unknown;
    valueType?: string;
};

/**
 * UnfurlRequest is the request body: the shared frontend URL, already
 * HTML-unescaped by the caller (Slack's link_shared event carries an
 * HTML-escaped URL; unescaping it before this endpoint sees it is what keeps
 * literal &amp; and &lt; out of the resolved card).
 */
export type UnfurlRequest = {
    url: string;
};

/**
 * UnfurlSlowestSpan is the slowest span of the trace excluding the card's root
 * (which would just restate the trace duration).
 */
export type UnfurlSlowestSpan = {
    durationSeconds?: number;
    name?: string;
};

/**
 * UnfurlTraceRequest identifies the trace a shared link points at, verbatim
 * from the link's drawer state. SpanID and Source drive the eBPF resolution:
 * an eBPF drawer's traceId is the span's own raw id, so the propagated id must
 * be resolved via span details before the waterfall is queried.
 */
export type UnfurlTraceRequest = {
    /**
     * SourceType is the trace's source type ("eBPF", "rum", …).
     */
    sourceType?: string;
    spanId?: string;
    time: string;
    traceId: string;
};

/**
 * UnfurlTraceSummary is the flat card-ready summary of a trace: exactly what a
 * link-unfurl card renders, nothing more. TraceID is the resolved (propagated)
 * id — the trace's stable identity regardless of which span the link came from.
 */
export type UnfurlTraceSummary = {
    durationSeconds?: number;
    errorCount?: number;
    /**
     * LimitReached marks a trace that reached UnfurlSpanLimit: SpanCount is then
     * a floor, not the trace's size.
     */
    limitReached?: boolean;
    operationName?: string;
    resource?: string;
    slowestSpan?: UnfurlSlowestSpan;
    spanCount?: number;
    spanName?: string;
    /**
     * StatusCode is the root span's protocol return code ("200", "500", a gRPC
     * code, …), empty for a protocol that has none.
     */
    statusCode?: string;
    traceId?: string;
};

/**
 * UnifiedSummary is the single hierarchical summary included in JSON output.
 */
export type UnifiedSummary = {
    assets?: AssetsSummary;
    /**
     * AssetsByFindingType is the distribution of affected assets per finding
     * type, keyed by asset type.
     */
    assets_by_finding_type?: {
        [key: string]: {
            [key: string]: number;
        };
    };
    conversion?: ConversionSummary;
    dashboards?: AssetFunnel;
    monitors?: AssetFunnel;
    queries?: QueriesSummary;
    wet_validation?: WetValidationSummary;
};

/**
 * Union defines a union operation between two pipelines (UNION ALL).
 */
export type Union = {
    leftPipeline?: SqlPipeline;
    rightPipeline?: SqlPipeline;
};

/**
 * UnsupportedAssetTypeBreakdown groups unsupported findings for a single asset type.
 */
export type UnsupportedAssetTypeBreakdown = {
    affected_assets?: number;
    by_reason?: OrderedReasons;
    count?: number;
    unit?: string;
};

/**
 * UnsupportedBreakdown is the Level 4 summary: why are things unsupported?
 *
 * Grouped first by asset type, then by the specific reason (conversion error message).
 */
export type UnsupportedBreakdown = {
    by_type?: {
        [key: string]: UnsupportedAssetTypeBreakdown;
    };
};

